import { useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, ArrowDownLeft, ArrowLeftRight, ArrowUpRight, Banknote, CalendarClock, CalendarDays, Check, ChevronLeft, ChevronRight, CircleAlert, ClipboardCheck, Download, FileClock, Filter, HardHat, LoaderCircle, Package, Plus, Search, Share2, ShoppingCart, Trash2, TrendingDown, TrendingUp, Wallet, Wrench, X } from 'lucide-react';
import { getAuthAccessToken } from './authClient.js';
import { apiUrl } from './apiUrl.js';

const brl = new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' });
const methods = { pix: 'Pix', cash: 'Dinheiro', card_debit: 'Débito', card_credit: 'Crédito', transfer: 'Transferência', boleto: 'Boleto', other: 'Outro' };
const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; };
const moneyText = (value) => brl.format(Number(value || 0));
const dayText = (value) => value ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(value).slice(0,10)}T12:00:00`)) : '—';
const dateRange = () => ({ from: `${today().slice(0,7)}-01`, to: today() });

async function apiRequest(path, options = {}) {
  const token = await getAuthAccessToken();
  const response = await fetch(`${apiUrl}${path}`, { ...options, headers: { Authorization: `Bearer ${token}`, ...(options.body ? { 'Content-Type':'application/json' } : {}), ...options.headers } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error?.message || 'Não foi possível concluir a operação.');
  return body;
}
function json(method, payload) { return { method, body: JSON.stringify(payload) }; }
function Heading({ eyebrow, title, description, action, accent = 'blue' }) { return <header className={`workspace-heading workspace-heading-${accent}`}><div><span className="workspace-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action&&<div className="workspace-heading-actions">{action}</div>}</header>; }
function Message({ error, notice, clear }) { return <>{error && <div className="workspace-message is-error" role="alert"><CircleAlert size={17}/><span>{error}</span></div>}{notice && <div className="workspace-message is-success" role="status"><Check size={17}/><span>{notice}</span><button onClick={clear} aria-label="Fechar"><X size={15}/></button></div>}</>; }
function Metric({ icon: Icon, label, value, note, tone='blue' }) { return <article className={`workspace-metric tone-${tone}`}><span><Icon size={17}/></span><small>{label}</small><strong>{value}</strong>{note && <em>{note}</em>}</article>; }
function SmallButton({ children, onClick, kind='secondary', disabled=false }) { return <button type="button" className={`workspace-button ${kind}`} disabled={disabled} onClick={onClick}>{children}</button>; }
async function serviceOrderPdf(order, company) {
  const { jsPDF } = await import('jspdf'); const doc = new jsPDF({unit:'mm',format:'a4'}); const margin=17; const right=193; const number=String(order.order_number).padStart(4,'0');
  doc.setFillColor(23,93,139);doc.rect(0,0,210,42,'F');doc.setTextColor(255,255,255);doc.setFont('helvetica','bold');doc.setFontSize(17);doc.text(company?.name||'EletroAgro',margin,18);doc.setFont('helvetica','normal');doc.setFontSize(10.5);doc.text('ORDEM DE SERVIÇO',right,18,{align:'right'});doc.setFont('helvetica','bold');doc.setFontSize(14);doc.text(`OS #${number}`,right,28,{align:'right'});
  let y=55;const field=(label,value)=>{if(y>263){doc.addPage();y=20;}doc.setFont('helvetica','bold');doc.setTextColor(23,93,139);doc.setFontSize(9.5);doc.text(label.toUpperCase(),margin,y);doc.setFont('helvetica','normal');doc.setTextColor(37,57,72);doc.setFontSize(11);const lines=doc.splitTextToSize(String(value||'—'),right-margin);doc.text(lines,margin,y+6);y+=8+lines.length*4.5;};
  field('Cliente',order.customer_name);field('Serviço',order.title);field('Endereço de execução',order.service_address);field('Descrição',order.description);field('Responsável',order.responsible_name);field('Prazo',dayText(order.due_date));field('Situação',({open:'Aberta',scheduled:'Agendada',in_progress:'Em execução',waiting_material:'Aguardando material',completed:'Concluída',cancelled:'Cancelada'})[order.status]||order.status);field('Valor estimado',moneyText(order.estimated_total));
  if(order.quote_number||order.sale_number){field('Documento de origem',order.quote_number?`Orçamento #${String(order.quote_number).padStart(4,'0')}`:`Venda #${String(order.sale_number).padStart(4,'0')}`);}
  if(order.items?.length){if(y>245){doc.addPage();y=20;}doc.setFont('helvetica','bold');doc.setTextColor(23,93,139);doc.setFontSize(10.5);doc.text('MATERIAIS REGISTRADOS',margin,y);y+=7;for(const item of order.items){doc.setFont('helvetica','normal');doc.setTextColor(50,75,91);doc.setFontSize(10.5);doc.text(`${item.name} — ${item.quantity} ${item.unit}`,margin,y);y+=6;}}
  if(order.notes){y+=8;if(y>265){doc.addPage();y=20;}doc.setFont('helvetica','bold');doc.setTextColor(23,93,139);doc.setFontSize(10.5);doc.text('OBSERVAÇÕES',margin,y);y+=6;doc.setFont('helvetica','normal');doc.setTextColor(103,119,132);doc.setFontSize(10.5);doc.text(doc.splitTextToSize(order.notes,176),margin,y);}
  const filename=`ordem-servico-${number}.pdf`;return {doc,filename};
}

export function OverviewPage({ onNavigate }) {
  const [data,setData]=useState(null);const [error,setError]=useState('');const [loading,setLoading]=useState(true);const [range,setRange]=useState('month');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const bounds=range==='week'?(()=>{const end=new Date();const start=new Date(end);start.setDate(end.getDate()-6);return {from:start.toISOString().slice(0,10),to:today()};})():range==='today'?{from:today(),to:today()}:{from:`${today().slice(0,7)}-01`,to:today()};setData(await apiRequest(`/api/operations/dashboard?from=${bounds.from}&to=${bounds.to}`));}catch(e){setError(e.message);}finally{setLoading(false);}},[range]);
  useEffect(()=>{load();},[load]);
  const attention=Number(data?.finance?.overdue||0)+Number(data?.orders?.overdue||0)+Number(data?.quotes?.expired||0);
  return <main className="workspace-page overview-workspace">
    <div className="overview-hero"><div className="overview-hero-copy"><span>GESTÃO ELETROAGRO</span><h1>Bom trabalho.<br/><em>Vamos cuidar do dia.</em></h1><p>Uma visão clara do que entrou, do que está em andamento e do que pede sua atenção.</p></div><div className="overview-hero-side"><CalendarDays size={20}/><span>{new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date())}</span><select aria-label="Período do painel" value={range} onChange={e=>setRange(e.target.value)}><option value="today">Hoje</option><option value="week">Últimos 7 dias</option><option value="month">Este mês</option></select></div><span className="overview-hero-mark"><Activity size={112}/></span></div>
    <Message error={error} clear={()=>setError('')}/>
    <div className="overview-section-top"><div><span className="workspace-eyebrow">AGORA</span><h2>O pulso da operação</h2></div><button className="text-refresh" onClick={load} disabled={loading}>{loading?<LoaderCircle size={15} className="spin"/>:'Atualizar dados'}</button></div>
    <section className="overview-metrics">{loading&&!data?<div className="workspace-loading"><LoaderCircle className="spin"/>Carregando seus dados…</div>:<>
      <Metric icon={Wallet} label="Vendido no período" value={moneyText(data?.sales?.total)} note={`${data?.sales?.count||0} vendas concluídas`} tone="blue"/>
      <Metric icon={ArrowDownLeft} label="Recebido no período" value={moneyText(data?.finance?.income)} note="Entradas confirmadas" tone="green"/>
      <Metric icon={TrendingDown} label="Despesas pagas" value={moneyText(data?.finance?.expense)} note="Saídas confirmadas" tone="yellow"/>
      <Metric icon={ClipboardCheck} label="Orçamentos em aberto" value={data?.quotes?.open||0} note={`${data?.quotes?.approved||0} aprovados`} tone="ink"/>
    </>}</section>
    <section className="overview-content-grid"><div className="overview-main-column">
      <article className={`attention-panel ${attention?'has-attention':''}`}><div className="attention-icon"><CircleAlert size={20}/></div><div><span className="workspace-eyebrow">PONTO DE ATENÇÃO</span><h2>{attention?`${attention} item${attention===1?'':'s'} precisam de você`:'Tudo em dia por aqui'}</h2><p>{Number(data?.finance?.overdue||0)} conta(s) vencida(s) · {Number(data?.orders?.overdue||0)} serviço(s) atrasado(s) · {Number(data?.quotes?.expired||0)} orçamento(s) expirado(s)</p></div><button onClick={()=>onNavigate('finance')}>Revisar pendências <ChevronRight size={16}/></button></article>
      <article className="overview-activity-panel"><div className="overview-section-top"><div><span className="workspace-eyebrow">ACOMPANHAMENTO</span><h2>Atividade recente</h2></div><button className="text-refresh" onClick={()=>onNavigate('audit')}>Abrir histórico <ChevronRight size={15}/></button></div>{data?.activity?.length?<div className="activity-timeline">{data.activity.map((item)=><div className="activity-event" key={item.id}><span className="activity-event-dot"/><div><strong>{activityLabel(item)}</strong><small>{String(item.entity_type).replaceAll('_',' ')}{item.summary?.title?` · ${item.summary.title}`:''}</small></div><time>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(item.created_at))}</time></div>)}</div>:<div className="activity-empty"><Activity size={20}/><span>{loading?'Carregando…':'As ações importantes aparecerão aqui conforme forem registradas.'}</span></div>}</article>
    </div><aside className="overview-side-column"><article className="quick-actions-panel"><span className="workspace-eyebrow">ATALHOS</span><h2>O que vamos fazer?</h2><button onClick={()=>onNavigate('quotes')}><span className="quick-action-icon blue"><FileClock size={17}/></span><span><b>Novo orçamento</b><small>Prepare uma proposta</small></span><ChevronRight size={16}/></button><button onClick={()=>onNavigate('sales')}><span className="quick-action-icon green"><Banknote size={17}/></span><span><b>Registrar venda</b><small>Nova ou de orçamento</small></span><ChevronRight size={16}/></button><button onClick={()=>onNavigate('orders')}><span className="quick-action-icon yellow"><Wrench size={17}/></span><span><b>Abrir ordem de serviço</b><small>Organize a execução</small></span><ChevronRight size={16}/></button></article>
      <article className="upcoming-panel"><span className="workspace-eyebrow">NA AGENDA</span><h2>Próximos compromissos</h2>{data?.upcoming?.length?data.upcoming.map(item=><button key={item.id} className="upcoming-row" onClick={()=>onNavigate('agenda')}><span className="upcoming-date"><b>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit'}).format(new Date(item.starts_at))}</b><small>{new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(new Date(item.starts_at))}</small></span><span><b>{item.title}</b><small>{new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(item.starts_at))}{item.address?` · ${item.address}`:''}</small></span></button>):<div className="upcoming-empty"><CalendarClock size={20}/><span>Nenhum compromisso futuro.</span><button onClick={()=>onNavigate('agenda')}>Planejar agenda</button></div>}</article></aside></section>
    <footer className="workspace-footnote">Os valores financeiros mostram apenas recebimentos e pagamentos registrados. Consulte o Financeiro para conferir pendências e vencimentos.</footer>
  </main>;
}

function activityLabel(item){const names={created:'Criado',payment_recorded:'Pagamento registrado',status_changed:'Situação atualizada',cancelled:'Cancelado',stock_movement:'Estoque movimentado'};return `${names[item.action]||item.action} · ${item.summary?.title||item.summary?.orderNumber&&`OS ${item.summary.orderNumber}`||item.summary?.saleNumber&&`Venda ${item.summary.saleNumber}`||''}`.trim();}

export function FinancePage(){
  const [entries,setEntries]=useState([]);const [summary,setSummary]=useState({income:'0',expense:'0',receivable:'0',payable:'0',overdue_count:0});const [range,setRange]=useState(dateRange);const [kind,setKind]=useState('all');const [status,setStatus]=useState('all');const [query,setQuery]=useState('');const [applied,setApplied]=useState('');const [draft,setDraft]=useState(null);const [payment,setPayment]=useState(null);const [customers,setCustomers]=useState([]);const [suppliers,setSuppliers]=useState([]);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const load=useCallback(async()=>{setLoading(true);setError('');try{const p=new URLSearchParams({type:kind,status,q:applied,from:range.from,to:range.to});const r=await apiRequest(`/api/operations/finance?${p}`);setEntries(r.entries);setSummary(r.summary);}catch(e){setError(e.message);}finally{setLoading(false);}},[kind,status,applied,range]);
  useEffect(()=>{load();},[load]);
  async function startEntry(type){setBusy(true);setError('');try{const [c,s]=await Promise.all([apiRequest('/api/customers?limit=100'),apiRequest('/api/suppliers?limit=100')]);setCustomers(c.customers||[]);setSuppliers(s.suppliers||[]);setDraft({entryType:type,title:'',amount:'',competenceDate:today(),dueDate:'',status:'pending',paymentMethod:'pix',settledAt:today(),customerId:'',supplierId:'',notes:''});}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function save(event){event.preventDefault();setBusy(true);setError('');try{await apiRequest('/api/operations/finance',json('POST',draft));setDraft(null);setNotice('Lançamento registrado.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function settle(event){event.preventDefault();setBusy(true);setError('');try{await apiRequest(`/api/operations/finance/${payment.entry.id}/payments`,json('POST',payment));setPayment(null);setNotice('Pagamento registrado.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  function exportCsv(){const rows=[['Descrição','Tipo','Situação','Cliente/Fornecedor','Vencimento','Valor','Recebido/Pago','Saldo'],...entries.map(e=>[e.title,e.entry_type==='income'?'Receita':'Despesa',e.status==='settled'?'Liquidado':e.status==='cancelled'?'Cancelado':'Pendente',e.customer_name||e.supplier_name||'',e.due_date||'',e.amount,e.amount_paid,e.balance])];const csv='\ufeff'+rows.map(row=>row.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`financeiro-${today()}.csv`;a.click();URL.revokeObjectURL(a.href);}
  return <main className="workspace-page finance-workspace"><Heading eyebrow="CAIXA E CONTAS" title="Financeiro" description="Acompanhe o que já entrou, o que falta receber e as contas da operação." accent="green" action={<button className="workspace-button primary" disabled={busy} onClick={()=>startEntry('income')}><Plus size={16}/> Novo lançamento</button>}/><Message error={error} notice={notice} clear={()=>setNotice('')}/>
    <section className="finance-ledger-hero"><div className="finance-ledger-intro"><span>RESUMO DE CAIXA</span><h2>Dinheiro acompanhado<br/>de ponta a ponta.</h2><p>Entradas e saídas realizadas são calculadas pelos pagamentos registrados.</p></div><div className="finance-flow"><div><small><ArrowDownLeft size={14}/> Entrou</small><strong>{moneyText(summary.income)}</strong></div><div><small><ArrowUpRight size={14}/> Saiu</small><strong>{moneyText(summary.expense)}</strong></div><div><small>Saldo realizado</small><strong>{moneyText(Number(summary.income)-Number(summary.expense))}</strong></div></div></section>
    <section className="finance-mini-metrics"><Metric icon={ArrowDownLeft} label="A receber" value={moneyText(summary.receivable)} note="Saldo de receitas pendentes" tone="green"/><Metric icon={ArrowUpRight} label="A pagar" value={moneyText(summary.payable)} note="Saldo de despesas pendentes" tone="yellow"/><Metric icon={CircleAlert} label="Vencidas" value={summary.overdue_count||0} note="Lançamentos com vencimento passado" tone="red"/></section>
    <div className="finance-toolbar"><div className="finance-kind-tabs" role="tablist" aria-label="Tipo de lançamento">{[['all','Tudo'],['income','A receber'],['expense','A pagar']].map(([v,l])=><button role="tab" aria-selected={kind===v} className={kind===v?'selected':''} onClick={()=>setKind(v)} key={v}>{l}</button>)}</div><form className="workspace-search" onSubmit={e=>{e.preventDefault();setApplied(query.trim());}}><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar descrição, cliente ou fornecedor"/><button>Buscar</button></form><label>De<input type="date" value={range.from} max={range.to} onChange={e=>setRange({...range,from:e.target.value})}/></label><label>Até<input type="date" value={range.to} min={range.from} onChange={e=>setRange({...range,to:e.target.value})}/></label><button className="workspace-button subtle" onClick={exportCsv}><Download size={15}/> Exportar</button></div>
    <div className="finance-ledger-title"><div><span className="workspace-eyebrow">MOVIMENTAÇÕES</span><h2>Contas e lançamentos</h2></div><div><select value={status} onChange={e=>setStatus(e.target.value)} aria-label="Filtrar status"><option value="all">Todos os status</option><option value="pending">Pendentes</option><option value="settled">Liquidados</option><option value="cancelled">Cancelados</option></select><button className="workspace-button yellow" onClick={()=>startEntry('expense')}><Plus size={15}/> Registrar despesa</button></div></div>
    <div className="finance-table-frame"><table className="finance-table"><thead><tr><th>Movimento</th><th>Vencimento</th><th>Valor original</th><th>Pago / recebido</th><th>Em aberto</th><th>Situação</th><th>Ação</th></tr></thead><tbody>{loading?<tr><td colSpan="7" className="workspace-table-state"><LoaderCircle className="spin"/>Carregando o extrato…</td></tr>:entries.length?entries.map(e=><tr key={e.id} className={e.overdue?'overdue-row':''}><td><span className={`finance-type-glyph ${e.entry_type}`}><ArrowLeftRight size={15}/></span><div><strong>{e.title}</strong><small>{e.entry_type==='income'?'Receita':'Despesa'} · {e.customer_name||e.supplier_name||'Sem vínculo'}</small></div></td><td>{dayText(e.due_date||e.competence_date)}{e.overdue&&<small className="overdue-label">Vencida</small>}</td><td>{moneyText(e.amount)}</td><td>{moneyText(e.amount_paid)}</td><td><strong>{moneyText(e.balance)}</strong></td><td><span className={`finance-status ${e.status}`}>{e.status==='settled'?'Liquidado':e.status==='cancelled'?'Cancelado':Number(e.amount_paid)>0?'Parcial':'Pendente'}</span></td><td>{e.status==='pending'&&Number(e.balance)>0?<button className="ledger-settle" onClick={()=>setPayment({entry:e,amount:e.balance,paymentMethod:'pix',paidAt:today()})}>Registrar {e.entry_type==='income'?'recebimento':'pagamento'}</button>:<span className="ledger-origin">{e.source_type==='sale'?'Venda integrada':e.source_type==='purchase'?'Compra integrada':'Manual'}</span>}</td></tr>):<tr><td colSpan="7" className="workspace-table-state"><Wallet size={22}/><strong>Nenhum lançamento no período</strong><span>Registre uma receita ou despesa para começar a acompanhar o caixa.</span></td></tr>}</tbody></table></div>
    {draft&&<div className="workspace-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDraft(null)}><section className="workspace-modal finance-entry-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">NOVO REGISTRO</span><h2>{draft.entryType==='income'?'Registrar receita':'Registrar despesa'}</h2><button onClick={()=>setDraft(null)} aria-label="Fechar"><X/></button></header><form onSubmit={save}><label>Descrição<input required minLength="2" maxLength="180" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} placeholder="Ex.: compra de material, serviço…"/></label><div className="workspace-form-row"><label>Valor (R$)<input required type="number" min="0.01" step="0.01" value={draft.amount} onChange={e=>setDraft({...draft,amount:e.target.value})}/></label><label>Competência<input required type="date" value={draft.competenceDate} onChange={e=>setDraft({...draft,competenceDate:e.target.value})}/></label></div><div className="workspace-form-row"><label>Vencimento<input type="date" value={draft.dueDate} onChange={e=>setDraft({...draft,dueDate:e.target.value})}/></label><label>{draft.entryType==='income'?'Cliente':'Fornecedor'}<select value={draft.entryType==='income'?draft.customerId:draft.supplierId} onChange={e=>setDraft({...draft,[draft.entryType==='income'?'customerId':'supplierId']:e.target.value})}><option value="">Sem vínculo</option>{(draft.entryType==='income'?customers:suppliers).map(x=><option value={x.id} key={x.id}>{x.name}</option>)}</select></label></div><label>Condição inicial<select value={draft.status} onChange={e=>setDraft({...draft,status:e.target.value})}><option value="pending">Pendente</option><option value="settled">Já recebido / pago</option></select></label>{draft.status==='settled'&&<div className="workspace-form-row"><label>Data<input type="date" value={draft.settledAt} onChange={e=>setDraft({...draft,settledAt:e.target.value})}/></label><label>Forma<select value={draft.paymentMethod} onChange={e=>setDraft({...draft,paymentMethod:e.target.value})}>{Object.entries(methods).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label></div>}<label>Observações<textarea rows="3" maxLength="3000" value={draft.notes} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label><Message error={error}/><footer><SmallButton onClick={()=>setDraft(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>{busy?'Salvando…':'Salvar lançamento'}</button></footer></form></section></div>}
    {payment&&<div className="workspace-backdrop"><section className="workspace-modal finance-entry-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">BAIXA FINANCEIRA</span><h2>Registrar {payment.entry.entry_type==='income'?'recebimento':'pagamento'}</h2><button onClick={()=>setPayment(null)} aria-label="Fechar"><X/></button></header><form onSubmit={settle}><p className="finance-balance-callout">Saldo restante <strong>{moneyText(payment.entry.balance)}</strong></p><label>Valor<input required type="number" min="0.01" max={payment.entry.balance} step="0.01" value={payment.amount} onChange={e=>setPayment({...payment,amount:e.target.value})}/></label><div className="workspace-form-row"><label>Data<input type="date" required value={payment.paidAt} onChange={e=>setPayment({...payment,paidAt:e.target.value})}/></label><label>Forma<select value={payment.paymentMethod} onChange={e=>setPayment({...payment,paymentMethod:e.target.value})}>{Object.entries(methods).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label></div><Message error={error}/><footer><SmallButton onClick={()=>setPayment(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>{busy?'Salvando…':'Confirmar baixa'}</button></footer></form></section></div>}
  </main>;
}

export function ServiceOrdersPage(){
  const [orders,setOrders]=useState([]);const [customers,setCustomers]=useState([]);const [sources,setSources]=useState({quotes:[],sales:[]});const [stockProducts,setStockProducts]=useState([]);const [query,setQuery]=useState('');const [applied,setApplied]=useState('');const [draft,setDraft]=useState(null);const [details,setDetails]=useState(null);const [materialDraft,setMaterialDraft]=useState(null);const [pdfBusy,setPdfBusy]=useState(false);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const load=useCallback(async()=>{setLoading(true);try{const p=new URLSearchParams({q:applied});const r=await apiRequest(`/api/operations/service-orders?${p}`);setOrders(r.orders);}catch(e){setError(e.message);}finally{setLoading(false);}},[applied]);useEffect(()=>{load();},[load]);
  async function start(){setError('');setBusy(true);try{const [c,s]=await Promise.all([apiRequest('/api/customers?limit=100'),apiRequest('/api/operations/service-order-sources')]);setCustomers(c.customers||[]);setSources({quotes:s.quotes||[],sales:s.sales||[]});setDraft({customerId:'',quoteId:'',saleId:'',title:'',description:'',priority:'normal',dueDate:'',scheduledAt:'',responsibleName:'',estimatedTotal:'0',serviceAddress:'',notes:''});}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function chooseSource(value){setError('');if(!value){setDraft({...draft,quoteId:'',saleId:''});return;}setBusy(true);try{const [type,id]=value.split(':');if(type==='quote'){const r=await apiRequest(`/api/quotes/${id}`);setDraft({...draft,quoteId:id,saleId:'',customerId:r.quote.customer_id||'',title:`Serviço do orçamento #${String(r.quote.quote_number).padStart(4,'0')}`,description:r.quote.terms||r.quote.notes||'',estimatedTotal:String(r.quote.total||'0')});}else{const r=await apiRequest(`/api/sales/${id}`);setDraft({...draft,saleId:id,quoteId:'',customerId:r.sale.customer_id||'',title:`Serviço da venda #${String(r.sale.sale_number).padStart(4,'0')}`,description:r.sale.notes||'',estimatedTotal:String(r.sale.total||'0')});}}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function save(e){e.preventDefault();setBusy(true);try{await apiRequest('/api/operations/service-orders',json('POST',draft));setDraft(null);setNotice('Ordem de serviço aberta.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function move(order,status){setBusy(true);try{await apiRequest(`/api/operations/service-orders/${order.id}/status`,json('PATCH',{status}));setNotice(`OS #${String(order.order_number).padStart(4,'0')} atualizada.`);await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function openDetails(order){setBusy(true);setError('');try{const [d,s]=await Promise.all([apiRequest(`/api/operations/service-orders/${order.id}`),apiRequest('/api/operations/stock')]);setDetails(d.order);setStockProducts(s.items.filter(i=>Number(i.stock)>0));setMaterialDraft({catalogItemId:'',quantity:'1',notes:''});}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function addMaterial(e){e.preventDefault();if(!details||!materialDraft)return;setBusy(true);setError('');try{await apiRequest(`/api/operations/service-orders/${details.id}/materials`,json('POST',materialDraft));const d=await apiRequest(`/api/operations/service-orders/${details.id}`);const s=await apiRequest('/api/operations/stock');setDetails(d.order);setStockProducts(s.items.filter(i=>Number(i.stock)>0));setNotice('Material registrado e saldo atualizado.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function downloadOrderPdf(){if(!details)return;setPdfBusy(true);try{const c=await apiRequest('/api/company/me');const {doc,filename}=await serviceOrderPdf(details,c.company);doc.save(filename);}catch(e){setError(e.message);}finally{setPdfBusy(false);}}
  async function shareOrderPdf(){if(!details)return;setPdfBusy(true);try{const c=await apiRequest('/api/company/me');const {doc,filename}=await serviceOrderPdf(details,c.company);const file=new File([doc.output('blob')],filename,{type:'application/pdf'});if(navigator.canShare?.({files:[file]}))await navigator.share({files:[file],title:`OS #${String(details.order_number).padStart(4,'0')}`,text:details.title});else doc.save(filename);}catch(e){if(e.name!=='AbortError')setError(e.message);}finally{setPdfBusy(false);}}
  const columns=[['open','Abertas'],['scheduled','Agendadas'],['in_progress','Em execução'],['waiting_material','Aguardando material'],['completed','Concluídas'],['cancelled','Canceladas']];const labels={open:'Aberta',scheduled:'Agendada',in_progress:'Em execução',waiting_material:'Aguardando material',completed:'Concluída',cancelled:'Cancelada'};
  return <main className="workspace-page orders-workspace"><Heading eyebrow="CAMPO E EXECUÇÃO" title="Ordens de serviço" description="Do combinado ao serviço concluído, com responsável, prazo e prioridade." accent="yellow" action={<button className="workspace-button primary" onClick={start} disabled={busy}><Plus size={16}/> Abrir ordem</button>}/><Message error={error} notice={notice} clear={()=>setNotice('')}/>
    <div className="orders-toolbar"><form className="workspace-search" onSubmit={e=>{e.preventDefault();setApplied(query.trim());}}><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar OS, cliente ou serviço"/><button>Buscar</button></form><span><HardHat size={15}/> {orders.filter(o=>!['completed','cancelled'].includes(o.status)).length} serviços ativos</span></div>
    {loading?<div className="workspace-loading"><LoaderCircle className="spin"/>Organizando a fila…</div>:<div className="orders-board">{columns.map(([key,title])=>{const list=orders.filter(o=>o.status===key);return <section className={`orders-lane lane-${key}`} key={key}><header><span className="orders-lane-dot"/><h2>{title}</h2><b>{list.length}</b></header><div className="orders-lane-content">{list.map(o=><article className={`order-work-card priority-${o.priority}`} key={o.id}><div className="order-card-top"><span>OS #{String(o.order_number).padStart(4,'0')}</span>{o.overdue&&<em>ATRASADA</em>}</div><h3>{o.title}</h3><p>{o.customer_name}</p>{o.quote_number&&<small className="order-source-pill">Orçamento #{String(o.quote_number).padStart(4,'0')}</small>}{o.sale_number&&<small className="order-source-pill">Venda #{String(o.sale_number).padStart(4,'0')}</small>}<div className="order-card-meta"><span><CalendarDays size={13}/>{dayText(o.due_date)}</span><span><Wallet size={13}/>{moneyText(o.estimated_total)}</span></div>{o.responsible_name&&<small className="order-responsible">Responsável · {o.responsible_name}</small>}<button className="order-open-details" onClick={()=>openDetails(o)}>Ver ordem <ChevronRight size={13}/></button><select aria-label={`Situação da ordem ${o.order_number}`} value={o.status} disabled={busy} onChange={e=>move(o,e.target.value)}>{columns.map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></article>)}{!list.length&&<div className="orders-lane-empty">{orders.length?'Sem OS nesta etapa':'Cadastre a primeira ordem de serviço.'}</div>}</div></section>;})}</div>}
    {details&&<div className="workspace-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDetails(null)}><section className="workspace-modal order-details-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">ORDEM DE SERVIÇO #{String(details.order_number).padStart(4,'0')}</span><h2>{details.title}</h2><button onClick={()=>setDetails(null)} aria-label="Fechar"><X/></button></header><div className="order-detail-client"><b>{details.customer_name}</b><span>{labels[details.status]} · {moneyText(details.estimated_total)}</span>{details.quote_number&&<small>Originada do orçamento #{String(details.quote_number).padStart(4,'0')}</small>}{details.sale_number&&<small>Originada da venda #{String(details.sale_number).padStart(4,'0')}</small>}</div>{details.service_address&&<p className="order-detail-copy"><b>Local</b>{details.service_address}</p>}{details.description&&<p className="order-detail-copy"><b>Descrição</b>{details.description}</p>}<div className="order-detail-facts"><span><small>PRAZO</small><b>{dayText(details.due_date)}</b></span><span><small>RESPONSÁVEL</small><b>{details.responsible_name||'Não definido'}</b></span><span><small>PRIORIDADE</small><b>{details.priority}</b></span></div>{details.notes&&<p className="order-detail-copy"><b>Observações</b>{details.notes}</p>}<section className="order-materials"><header><div><span className="workspace-eyebrow">SAÍDA DO ESTOQUE</span><h3>Materiais utilizados</h3></div></header>{details.items.length?details.items.map(item=><div className="order-material-row" key={item.id}><span>{item.name}</span><b>{item.quantity} {item.unit}</b></div>):<p className="order-no-material">Nenhum material registrado nesta OS.</p>}{!['completed','cancelled'].includes(details.status)&&<form className="order-material-form" onSubmit={addMaterial}><label>Material<select required value={materialDraft?.catalogItemId||''} onChange={e=>setMaterialDraft({...materialDraft,catalogItemId:e.target.value})}><option value="">Produto disponível</option>{stockProducts.map(item=><option value={item.id} key={item.id}>{item.name} · saldo {item.stock} {item.unit}</option>)}</select></label><label>Quantidade<input required type="number" min="0.001" step="0.001" value={materialDraft?.quantity||'1'} onChange={e=>setMaterialDraft({...materialDraft,quantity:e.target.value})}/></label><button className="workspace-button primary" disabled={busy}><Plus size={14}/> Registrar uso</button></form>}</section><div className="order-detail-actions"><button className="workspace-button subtle" onClick={downloadOrderPdf} disabled={pdfBusy}><Download size={14}/> Imprimir PDF</button><button className="workspace-button subtle" onClick={shareOrderPdf} disabled={pdfBusy}><Share2 size={14}/> Compartilhar</button><button className="workspace-button" onClick={()=>setDetails(null)}>Fechar</button></div><Message error={error}/></section></div>}
    {draft&&<div className="workspace-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDraft(null)}><section className="workspace-modal order-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">NOVA EXECUÇÃO</span><h2>Abrir ordem de serviço</h2><button onClick={()=>setDraft(null)} aria-label="Fechar"><X/></button></header><form onSubmit={save}><label>Vincular a um orçamento ou venda<select value={draft.quoteId?`quote:${draft.quoteId}`:draft.saleId?`sale:${draft.saleId}`:''} disabled={busy} onChange={e=>chooseSource(e.target.value)}><option value="">Criar serviço sem documento de origem</option>{sources.quotes.length>0&&<optgroup label="Orçamentos aprovados">{sources.quotes.map(q=><option key={q.id} value={`quote:${q.id}`}>Orçamento #{String(q.quote_number).padStart(4,'0')} · {q.customer_name} · {moneyText(q.total)}</option>)}</optgroup>}{sources.sales.length>0&&<optgroup label="Vendas">{sources.sales.map(s=><option key={s.id} value={`sale:${s.id}`}>Venda #{String(s.sale_number).padStart(4,'0')} · {s.customer_name} · {moneyText(s.total)}</option>)}</optgroup>}</select><small className="order-source-help">O vínculo importa cliente, descrição e valor como ponto de partida.</small></label><div className="workspace-form-row"><label>Cliente<select required disabled={Boolean(draft.quoteId||draft.saleId)} value={draft.customerId} onChange={e=>setDraft({...draft,customerId:e.target.value})}><option value="">Selecione</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Nome do serviço<input required minLength="2" maxLength="180" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label></div><label>Descrição do trabalho<textarea rows="3" maxLength="5000" value={draft.description} onChange={e=>setDraft({...draft,description:e.target.value})}/></label><label>Endereço de execução<input maxLength="500" value={draft.serviceAddress} onChange={e=>setDraft({...draft,serviceAddress:e.target.value})}/></label><div className="workspace-form-row"><label>Prioridade<select value={draft.priority} onChange={e=>setDraft({...draft,priority:e.target.value})}><option value="normal">Normal</option><option value="low">Baixa</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label><label>Responsável<input maxLength="120" value={draft.responsibleName} onChange={e=>setDraft({...draft,responsibleName:e.target.value})}/></label></div><div className="workspace-form-row"><label>Prazo<input type="date" value={draft.dueDate} onChange={e=>setDraft({...draft,dueDate:e.target.value})}/></label><label>Valor estimado (R$)<input type="number" min="0" step="0.01" value={draft.estimatedTotal} onChange={e=>setDraft({...draft,estimatedTotal:e.target.value})}/></label></div><label>Observações<textarea rows="2" maxLength="3000" value={draft.notes} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label><Message error={error}/><footer><SmallButton onClick={()=>setDraft(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>Criar ordem</button></footer></form></section></div>}
  </main>;
}

export function AgendaPage(){
  const [week,setWeek]=useState(()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));return d;});const [selectedDay,setSelectedDay]=useState(today());const [appointments,setAppointments]=useState([]);const [customers,setCustomers]=useState([]);const [orders,setOrders]=useState([]);const [draft,setDraft]=useState(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const dateKey=(d)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const days=useMemo(()=>Array.from({length:7},(_,i)=>{const d=new Date(week);d.setDate(d.getDate()+i);return d;}),[week]);const from=dateKey(days[0]);const to=dateKey(days[6]);
  const load=useCallback(async()=>{setLoading(true);try{const [a,c,o]=await Promise.all([apiRequest(`/api/operations/appointments?from=${from}&to=${to}`),apiRequest('/api/customers?limit=100'),apiRequest('/api/operations/service-orders?status=all')]);setAppointments(a.appointments);setCustomers(c.customers||[]);setOrders(o.orders||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[from,to]);useEffect(()=>{load();},[load]);
  async function save(e){e.preventDefault();setBusy(true);try{const payload={...draft,startsAt:new Date(draft.startsAt).toISOString(),endsAt:draft.endsAt?new Date(draft.endsAt).toISOString():null};await apiRequest('/api/operations/appointments',json('POST',payload));setDraft(null);setNotice('Compromisso adicionado à agenda.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function status(item,next){setBusy(true);try{await apiRequest(`/api/operations/appointments/${item.id}/status`,json('PATCH',{status:next}));await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  function shift(n){const d=new Date(week);d.setDate(d.getDate()+7*n);setWeek(d);setSelectedDay(dateKey(d));}
  return <main className="workspace-page agenda-workspace"><Heading eyebrow="TEMPO E DESLOCAMENTOS" title="Agenda" description="Planeje atendimentos e organize a semana da equipe." accent="blue" action={<button className="workspace-button primary" onClick={()=>setDraft({title:'',startsAt:`${selectedDay}T09:00`,endsAt:`${selectedDay}T10:00`,customerId:'',serviceOrderId:'',address:'',notes:''})}><Plus size={16}/> Novo compromisso</button>}/><Message error={error} notice={notice} clear={()=>setNotice('')}/>
    <section className="agenda-week-header"><div><span className="workspace-eyebrow">SEMANA DE TRABALHO</span><h2>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(days[0])} — {new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric'}).format(days[6])}</h2></div><div><button onClick={()=>shift(-1)} aria-label="Semana anterior"><ChevronLeft/></button><button onClick={()=>{const d=new Date();d.setDate(d.getDate()-((d.getDay()+6)%7));setWeek(d);setSelectedDay(today());}}>Hoje</button><button onClick={()=>shift(1)} aria-label="Próxima semana"><ChevronRight/></button></div></section>
    <nav className="agenda-day-strip">{days.map(d=>{const key=dateKey(d);const count=appointments.filter(a=>dateKey(new Date(a.starts_at))===key&&a.status==='scheduled').length;return <button key={key} className={`${key===today()?'today':''} ${key===selectedDay?'selected':''}`} onClick={()=>setSelectedDay(key)}><small>{new Intl.DateTimeFormat('pt-BR',{weekday:'short'}).format(d)}</small><strong>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit'}).format(d)}</strong>{count>0&&<i>{count}</i>}</button>;})}</nav>
    {loading?<div className="workspace-loading"><LoaderCircle className="spin"/>Consultando a agenda…</div>:<div className="agenda-day-list">{days.filter(d=>dateKey(d)===selectedDay).map(d=>{const key=dateKey(d);const list=appointments.filter(a=>dateKey(new Date(a.starts_at))===key);return <section className="agenda-day" key={key}><header><span>{new Intl.DateTimeFormat('pt-BR',{weekday:'long'}).format(d)}</span><strong>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long'}).format(d)}</strong></header><div className="agenda-day-events">{list.length?list.map(a=><article className={`agenda-event ${a.status}`} key={a.id}><time>{new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(a.starts_at))}{a.ends_at?`–${new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(a.ends_at))}`:''}</time><div><h3>{a.title}</h3><p>{a.customer_name||'Sem cliente'}{a.address?` · ${a.address}`:''}</p>{a.order_number&&<small>OS #{String(a.order_number).padStart(4,'0')}</small>}</div><select aria-label={`Situação de ${a.title}`} value={a.status} disabled={busy} onChange={e=>status(a,e.target.value)}><option value="scheduled">Agendado</option><option value="completed">Concluído</option><option value="cancelled">Cancelado</option></select></article>):<div className="agenda-empty-day">Sem compromissos planejados</div>}</div></section>;})}</div>}
    {draft&&<div className="workspace-backdrop" onMouseDown={e=>e.target===e.currentTarget&&setDraft(null)}><section className="workspace-modal agenda-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">PLANEJAMENTO</span><h2>Novo compromisso</h2><button onClick={()=>setDraft(null)} aria-label="Fechar"><X/></button></header><form onSubmit={save}><label>Atendimento<input required minLength="2" maxLength="180" value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})}/></label><div className="workspace-form-row"><label>Início<input type="datetime-local" required value={draft.startsAt} onChange={e=>setDraft({...draft,startsAt:e.target.value})}/></label><label>Fim<input type="datetime-local" value={draft.endsAt} onChange={e=>setDraft({...draft,endsAt:e.target.value})}/></label></div><div className="workspace-form-row"><label>Cliente<select value={draft.customerId} onChange={e=>setDraft({...draft,customerId:e.target.value})}><option value="">Sem cliente</option>{customers.map(c=><option value={c.id} key={c.id}>{c.name}</option>)}</select></label><label>Ordem de serviço<select value={draft.serviceOrderId} onChange={e=>setDraft({...draft,serviceOrderId:e.target.value})}><option value="">Sem ordem vinculada</option>{orders.filter(o=>!['completed','cancelled'].includes(o.status)).map(o=><option value={o.id} key={o.id}>OS #{String(o.order_number).padStart(4,'0')} · {o.title}</option>)}</select></label></div><label>Endereço<input maxLength="500" value={draft.address} onChange={e=>setDraft({...draft,address:e.target.value})}/></label><label>Observações<textarea rows="3" maxLength="3000" value={draft.notes} onChange={e=>setDraft({...draft,notes:e.target.value})}/></label><Message error={error}/><footer><SmallButton onClick={()=>setDraft(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>Agendar</button></footer></form></section></div>}
  </main>;
}

export function StockPage(){
  const [items,setItems]=useState([]);const [movements,setMovements]=useState([]);const [query,setQuery]=useState('');const [applied,setApplied]=useState('');const [catalog,setCatalog]=useState([]);const [suppliers,setSuppliers]=useState([]);const [draft,setDraft]=useState(null);const [purchase,setPurchase]=useState(null);const [loading,setLoading]=useState(true);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [notice,setNotice]=useState('');
  const load=useCallback(async()=>{setLoading(true);try{const [s,c,p]=await Promise.all([apiRequest(`/api/operations/stock?q=${encodeURIComponent(applied)}`),apiRequest('/api/catalog?type=product&status=active'),apiRequest('/api/suppliers?limit=100')]);setItems(s.items);setMovements(s.movements);setCatalog(c.items||[]);setSuppliers(p.suppliers||[]);}catch(e){setError(e.message);}finally{setLoading(false);}},[applied]);useEffect(()=>{load();},[load]);
  async function saveMovement(e){e.preventDefault();setBusy(true);try{await apiRequest('/api/operations/stock/movements',json('POST',draft));setDraft(null);setNotice('Movimentação de estoque registrada.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function savePurchase(e){e.preventDefault();setBusy(true);try{const payload={supplierId:purchase.supplierId,purchaseDate:purchase.purchaseDate,dueDate:purchase.dueDate,amountPaid:purchase.amountPaid,paymentMethod:purchase.paymentMethod,notes:purchase.notes,items:purchase.items.filter(i=>i.catalogItemId&&i.quantity&&i.unitCost)};await apiRequest('/api/operations/purchases',json('POST',payload));setPurchase(null);setNotice('Compra registrada, estoque atualizado e conta a pagar integrada.');await load();}catch(e){setError(e.message);}finally{setBusy(false);}}
  const low=items.filter(i=>Number(i.stock)<=Number(i.minimum_stock)&&Number(i.minimum_stock)>0).length;const value=items.reduce((s,i)=>s+Number(i.stock)*Number(i.cost_price||0),0);
  return <main className="workspace-page stock-workspace"><Heading eyebrow="MATERIAIS E COMPRAS" title="Estoque" description="Saldo atual, movimentações rastreáveis e entradas integradas às compras." accent="yellow" action={<><button className="workspace-button subtle" onClick={()=>setPurchase({supplierId:'',purchaseDate:today(),dueDate:'',amountPaid:'0',paymentMethod:'pix',notes:'',items:[{catalogItemId:'',quantity:'1',unitCost:'0'}]})}><ShoppingCart size={16}/> Registrar compra</button><button className="workspace-button primary" onClick={()=>setDraft({catalogItemId:'',direction:'in',quantity:'1',unitCost:'',reason:''})}><Plus size={16}/> Movimentar</button></>}/><Message error={error} notice={notice} clear={()=>setNotice('')}/>
    <section className="stock-overview"><div className="stock-total-card"><div><span className="workspace-eyebrow">MATERIAIS CADASTRADOS</span><strong>{items.length}</strong><p>Produtos ativos com acompanhamento de saldo.</p></div><Package size={38}/></div><div className="stock-stat"><span>Estoque baixo</span><strong className={low?'low-stock-count':''}>{low}</strong><small>Produtos no mínimo ou abaixo</small></div><div className="stock-stat"><span>Últimos movimentos</span><strong>{movements.length}</strong><small>Registros recentes</small></div><div className="stock-stat"><span>Itens pesquisados</span><strong>{items.filter(i=>Number(i.stock)>0).length}</strong><small>Com saldo positivo</small></div></section>
    <div className="stock-toolbar"><div><span className="workspace-eyebrow">POSIÇÃO ATUAL</span><h2>Saldo por produto</h2></div><form className="workspace-search" onSubmit={e=>{e.preventDefault();setApplied(query.trim());}}><Search size={15}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar produto ou código"/><button>Buscar</button></form></div>
    <div className="stock-table-frame"><table className="stock-table"><thead><tr><th>Produto</th><th>Código</th><th>Saldo</th><th>Estoque mínimo</th><th>Indicador</th><th>Ação</th></tr></thead><tbody>{loading?<tr><td colSpan="6" className="workspace-table-state"><LoaderCircle className="spin"/>Atualizando saldos…</td></tr>:items.length?items.map(i=>{const isLow=Number(i.stock)<=Number(i.minimum_stock)&&Number(i.minimum_stock)>0;return <tr key={i.id}><td><strong>{i.name}</strong></td><td>{i.code||'—'}</td><td><b className="stock-quantity">{Number(i.stock).toLocaleString('pt-BR',{maximumFractionDigits:3})} <small>{i.unit}</small></b></td><td>{Number(i.minimum_stock).toLocaleString('pt-BR',{maximumFractionDigits:3})} {i.unit}</td><td><span className={`stock-indicator ${isLow?'low':'ok'}`}>{isLow?'Repor':'Saudável'}</span></td><td><button className="stock-quick-move" onClick={()=>setDraft({catalogItemId:i.id,direction:'in',quantity:'1',unitCost:'',reason:'Reposição'})}>+ Entrada</button><button className="stock-quick-move out" onClick={()=>setDraft({catalogItemId:i.id,direction:'out',quantity:'1',unitCost:'',reason:'Uso operacional'})}>− Saída</button></td></tr>; }):<tr><td colSpan="6" className="workspace-table-state"><Package size={22}/><strong>Nenhum produto ativo no catálogo</strong><span>Cadastre produtos para controlar seus saldos.</span></td></tr>}</tbody></table></div>
    <section className="stock-movement-section"><header><div><span className="workspace-eyebrow">TRILHA DE MOVIMENTAÇÕES</span><h2>Histórico recente</h2></div><span>Entradas e saídas não apagam o passado</span></header><div className="stock-movement-list">{movements.length?movements.map(m=><article key={m.id}><span className={`movement-glyph ${m.direction}`}>{m.direction==='in'?<ArrowDownLeft size={17}/>:<ArrowUpRight size={17}/>}</span><div><strong>{m.item_name}</strong><small>{m.reason} · {new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(m.created_at))}</small></div><b className={m.direction==='in'?'positive':'negative'}>{m.direction==='in'?'+':'−'}{Number(m.quantity).toLocaleString('pt-BR',{maximumFractionDigits:3})} {m.unit}</b></article>):<p className="activity-empty">Os movimentos registrados aparecerão aqui.</p>}</div></section>
    {draft&&<div className="workspace-backdrop"><section className="workspace-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">LIVRO DE ESTOQUE</span><h2>Registrar movimento</h2><button onClick={()=>setDraft(null)} aria-label="Fechar"><X/></button></header><form onSubmit={saveMovement}><label>Produto<select required value={draft.catalogItemId} onChange={e=>setDraft({...draft,catalogItemId:e.target.value})}><option value="">Selecione</option>{catalog.map(i=><option value={i.id} key={i.id}>{i.name}</option>)}</select></label><div className="workspace-form-row"><label>Movimento<select value={draft.direction} onChange={e=>setDraft({...draft,direction:e.target.value})}><option value="in">Entrada</option><option value="out">Saída</option></select></label><label>Quantidade<input required type="number" min="0.001" step="0.001" value={draft.quantity} onChange={e=>setDraft({...draft,quantity:e.target.value})}/></label></div>{draft.direction==='in'&&<label>Custo unitário (R$)<input type="number" min="0" step="0.01" value={draft.unitCost} onChange={e=>setDraft({...draft,unitCost:e.target.value})}/></label>}<label>Motivo<input required minLength="2" maxLength="300" value={draft.reason} onChange={e=>setDraft({...draft,reason:e.target.value})} placeholder="Compra, ajuste, uso em serviço…"/></label><Message error={error}/><footer><SmallButton onClick={()=>setDraft(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>Registrar movimento</button></footer></form></section></div>}
    {purchase&&<div className="workspace-backdrop"><section className="workspace-modal purchase-modal" role="dialog" aria-modal="true"><header><span className="workspace-eyebrow">ENTRADA DE MERCADORIA</span><h2>Registrar compra</h2><button onClick={()=>setPurchase(null)} aria-label="Fechar"><X/></button></header><form onSubmit={savePurchase}><div className="workspace-form-row"><label>Fornecedor<select value={purchase.supplierId} onChange={e=>setPurchase({...purchase,supplierId:e.target.value})}><option value="">Sem fornecedor</option>{suppliers.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>Data da compra<input type="date" value={purchase.purchaseDate} onChange={e=>setPurchase({...purchase,purchaseDate:e.target.value})}/></label></div><div className="purchase-lines"><header><strong>Produtos recebidos</strong><button type="button" onClick={()=>setPurchase({...purchase,items:[...purchase.items,{catalogItemId:'',quantity:'1',unitCost:'0'}]})}><Plus size={14}/> Adicionar produto</button></header>{purchase.items.map((item,index)=><div className="purchase-line" key={index}><label>Produto<select required value={item.catalogItemId} onChange={e=>setPurchase({...purchase,items:purchase.items.map((line,i)=>i===index?{...line,catalogItemId:e.target.value}:line)})}><option value="">Selecione um produto</option>{catalog.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><label>Quantidade<input required aria-label={`Quantidade do produto ${index+1}`} type="number" min="0.001" step="0.001" value={item.quantity} onChange={e=>setPurchase({...purchase,items:purchase.items.map((line,i)=>i===index?{...line,quantity:e.target.value}:line)})}/></label><label>Custo unitário<input required aria-label={`Custo unitário do produto ${index+1}`} type="number" min="0" step="0.01" value={item.unitCost} onChange={e=>setPurchase({...purchase,items:purchase.items.map((line,i)=>i===index?{...line,unitCost:e.target.value}:line)})}/></label>{purchase.items.length>1&&<button type="button" className="purchase-line-remove" aria-label={`Remover produto ${index+1}`} onClick={()=>setPurchase({...purchase,items:purchase.items.filter((_,i)=>i!==index)})}><Trash2 size={17}/></button>}</div>)}</div><div className="workspace-form-row"><label>Vencimento da conta<input type="date" value={purchase.dueDate} onChange={e=>setPurchase({...purchase,dueDate:e.target.value})}/></label><label>Valor pago agora (R$)<input type="number" min="0" step="0.01" value={purchase.amountPaid} onChange={e=>setPurchase({...purchase,amountPaid:e.target.value})}/></label></div>{Number(purchase.amountPaid)>0&&<label>Forma<select value={purchase.paymentMethod} onChange={e=>setPurchase({...purchase,paymentMethod:e.target.value})}>{Object.entries(methods).map(([v,l])=><option value={v} key={v}>{l}</option>)}</select></label>}<label>Observações<textarea rows="2" value={purchase.notes} onChange={e=>setPurchase({...purchase,notes:e.target.value})}/></label><Message error={error}/><footer><SmallButton onClick={()=>setPurchase(null)}>Cancelar</SmallButton><button className="workspace-button primary" disabled={busy}>Confirmar compra e entrada</button></footer></form></section></div>}
  </main>;
}

export function AuditPage(){const [items,setItems]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');useEffect(()=>{apiRequest('/api/operations/audit').then(r=>setItems(r.activity)).catch(e=>setError(e.message)).finally(()=>setLoading(false));},[]);return <main className="workspace-page audit-workspace"><Heading eyebrow="RASTREABILIDADE" title="Histórico de atividades" description="Ações comerciais, financeiras e operacionais registradas pela equipe." accent="ink"/><Message error={error}/><section className="audit-intro"><Activity size={20}/><div><b>O histórico preserva o contexto das mudanças</b><p>Cancelamentos, recebimentos, movimentações e alterações de situação ficam associados ao usuário e horário.</p></div></section><div className="audit-list">{loading?<div className="workspace-loading"><LoaderCircle className="spin"/>Carregando histórico…</div>:items.map(item=><article key={item.id}><span className={`audit-mark action-${item.action}`}>{item.action==='payment_recorded'?<Banknote size={16}/>:item.action==='stock_movement'?<Package size={16}/>:item.action==='cancelled'?<X size={16}/>:<Check size={16}/>}</span><div><b>{activityLabel(item)}</b><p>{String(item.entity_type).replaceAll('_',' ')}{item.summary?.reason?` · ${item.summary.reason}`:''}</p><small>{item.actor_subject}</small></div><time>{new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(item.created_at))}</time></article>)}{!loading&&!items.length&&<div className="workspace-table-state"><FileClock size={22}/>As atividades importantes aparecerão aqui.</div>}</div></main>;}

export function CompanyAccessPage({ user, onComplete, onSignOut }) {
  const [name,setName]=useState('');const [code,setCode]=useState('');const [mode,setMode]=useState('create');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  async function create(event){event.preventDefault();setBusy(true);setError('');try{const result=await apiRequest('/api/company',json('POST',{name}));onComplete(result.company);}catch(e){setError(e.message);}finally{setBusy(false);}}
  async function accept(event){event.preventDefault();setBusy(true);setError('');try{const result=await apiRequest('/api/company/invitations/accept',json('POST',{code:code.trim()}));onComplete(result.company);}catch(e){setError(e.message);}finally{setBusy(false);}}
  return <main className="company-access-screen"><section className="company-access-card"><div className="company-access-brand"><img src="/logo-eletroagro.jpeg" alt="EletroAgro"/></div><span className="workspace-eyebrow">CONFIGURAÇÃO DO ESPAÇO</span><h1>{mode==='create'?'Vamos organizar a empresa.':'Entrar na equipe.'}</h1><p>Olá, {user.name||user.email}. {user.databaseUnavailable?'O acesso está ativo, mas a API está sem banco configurado. Configure DATABASE_URL em apps/api/.env para continuar.':mode==='create'?'Crie o espaço compartilhado da sua empresa para começar.':'Use o código que o responsável da empresa compartilhou com você.'}</p>{!user.databaseUnavailable&&<><div className="company-access-switch"><button className={mode==='create'?'active':''} onClick={()=>{setMode('create');setError('');}}>Criar empresa</button><button className={mode==='accept'?'active':''} onClick={()=>{setMode('accept');setError('');}}>Tenho um convite</button></div>{mode==='create'?<form onSubmit={create}><label>Nome da empresa<input autoFocus required minLength="2" maxLength="160" value={name} onChange={e=>setName(e.target.value)} placeholder="Ex.: EletroAgro Soluções"/></label><small>Você será o responsável e poderá convidar até quatro pessoas.</small><button className="workspace-button primary" disabled={busy}>{busy?'Criando…':'Criar espaço da empresa'}</button></form>:<form onSubmit={accept}><label>Código de convite<input autoFocus required minLength="30" maxLength="100" value={code} onChange={e=>setCode(e.target.value)} placeholder="Cole aqui o código enviado pelo responsável"/></label><small>O convite fica vinculado ao e-mail desta conta: <b>{user.email}</b></small><button className="workspace-button primary" disabled={busy}>{busy?'Validando…':'Aceitar convite'}</button></form>}</>}{error&&<div className="workspace-message is-error" role="alert"><CircleAlert size={16}/>{error}</div>}<button className="company-access-signout" onClick={onSignOut}>Sair desta conta</button></section></main>;
}
